INSERT INTO `sys_oper_log` VALUES (535, '检测项管理', 2, 'com.ruoyi.system.controller.DInspectionItemController.edit()', 'PUT', 1, 'admin', '研发部门', '/system/inspectionItem', '127.0.0.1', '内网IP', '{\"children\":[{\"children\":[],\"id\":18,\"pid\":16,\"name\":\"消防配电\",\"requirements\":\"5.2.1.1.消防用电设备的供电回路应为专用回路。5.2.1.2. 消防设备配电箱应有区别于其他配电箱的明显标志，不同消防设备的配电箱应有明显区分标 识。配电箱上的仪表、指示灯的显示应正常，开关及控制按钮应灵活、可靠。5.2.1.3.消防控制室、消防水泵房、防烟与排烟机房的消防用电设备及消防电梯等的供电，应在其配电 线路的最末一级配电箱处具有主、备电源自动切换装置。切换备用电源的控制方式及操作程序应符合设 计要求，主备电的切换时间应符合设计要求。\",\"method\":\"6.2.1.1\\t核对消防配电方式，查看消防控制室及各消防设施最末一级配电箱的标志以及仪表、指示灯、 开关和控制按钮。6.2.1.2\\t核对各相关部位的配电方式、配电箱的控制方式和操作程序，进行以下试验并查看最末一级配 电箱运行情况：a）  自动控制方式下，手动切断消防主电源，观察备用消防电源的投入及指示灯的显示情况，记录 主备电源切换时间；b）  手动控制方式下，在低压配电室应先切断消防主电源，然后闭合备用消防电源，观察备用消防 电源的投入及指示灯的显示情况。\",\"deleted\":0,\"creator\":\"1\",\"creatorTime\":\"2026-01-26\",\"modifier\":\"1\",\"modifierTime\":\"2026-01-26\",\"isSubject\":false}],\"creator\":\"1\",\"creatorTime\":\"2026-01-26\",\"deleted\":0,\"id\":16,\"method\":\"%3Cp%3E%3Cbr%3E%3C%2Fp%3E\",\"modifier\":\"1\",\"modifierTime\":\"2026-01-26\",\"name\":\"消防供配电设施\",\"params\":{},\"pid\":15,\"requirements\":\"%3Cp%3E%3Cbr%3E%3C%2Fp%3E\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-01-26 16:54:51', 9);
