-- ----------------------------
-- Table structure for d_device_scan
-- ----------------------------
DROP TABLE IF EXISTS `d_device_scan`;
CREATE TABLE `d_device_scan`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `plan_id` bigint NOT NULL COMMENT '计划ID',
  `zone_id` bigint NULL DEFAULT NULL COMMENT '区域ID',
  `scan_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扫描二维码的图片地址',
  `scan_result` tinyint NOT NULL DEFAULT 0 COMMENT '检查状态（0-未检测，1-通过，2-不通过）',
  `scan_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注（不通过时填写理由）',
  `photos` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场照片（多个用逗号分隔）',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `creator_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `modifier` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '检查人员',
  `modifier_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '检查时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_plan_status`(`plan_id` ASC, `scan_result` ASC) USING BTREE COMMENT '按计划查进度',
  INDEX `idx_device`(`device_id` ASC) USING BTREE COMMENT '设备查询',
  INDEX `idx_modifier`(`modifier` ASC) USING BTREE COMMENT '检查人员查询'
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备检查状态表 - 状态：0未检测 1通过 2不通过' ROW_FORMAT = DYNAMIC;

