-- ----------------------------
-- Table structure for d_plan_user
-- ----------------------------
DROP TABLE IF EXISTS `d_plan_user`;
CREATE TABLE `d_plan_user`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NOT NULL COMMENT '计划ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `zone_id` bigint NOT NULL COMMENT '区域ID',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '检查状态（0-未检查，1-通过，2-不通过）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查备注',
  `photos` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场照片',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `creator_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `modifier` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改者（检查人员）',
  `modifier_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间（检查时间）',
  PRIMARY KEY (`id`) USING BTREE,
