  INDEX `idx_plan_zone`(`plan_id` ASC, `zone_id` ASC) USING BTREE COMMENT '按区域查询',
  INDEX `idx_device`(`device_id` ASC) USING BTREE COMMENT '按设备查询'
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '计划-人员-设备关联表（含检查状态跟踪）' ROW_FORMAT = DYNAMIC;

